style.css:
@-moz-document domain("cpm.org") {
/* Override the body background */
    body {
        background: url(https://th.bing.com/th/id/R.d08df49da7cdd8bcdbbd7b66a8ccddc9?rik=UJA%2bMIH9cB%2bGcA&riu=http%3a%2f%2fhdqwalls.com%2fwallpapers%2fnissan-gtr-5k-2019-uh.jpg&ehk=KwrQdxUFA7oSpVNu%2bGd26zE4RzcK6lQzKSMWgE5q1cE%3d&risl=1&pid=ImgRaw&r=0) no-repeat center center fixed !important;
        background-size: cover !important;
        font-family: 'Arial', sans-serif !important;
        color: #ffffff !important;
        margin: 0 !important;
        padding: 0 !important;
    }

    /* Override headers */
    header, .chapter h1, .chapter h2, .chapter h3 {
        background: rgba(0, 0, 0, 0.8) !important;
        padding: 20px !important;
        text-align: center !important;
        font-size: 24px !important;
        color: #ffcc00 !important;
        border-bottom: 3px solid #ff6600 !important;
    }

    /* Style navigation */
    nav, .sidebar nav {
        background: rgba(255, 102, 0, 0.9) !important;
        padding: 10px !important;
        text-align: center !important;
        border-bottom: 3px solid #ffcc00 !important;
    }

    nav a, .sidebar nav a {
        text-decoration: none !important;
        color: white !important;
        font-weight: bold !important;
        margin: 0 15px !important;
        font-size: 16px !important;
    }

    nav a:hover, .sidebar nav a:hover {
        color: #ffcc00 !important;
        text-shadow: 0px 0px 10px #ffffff !important;
    }

    /* Override the chapter and sidebar appearance */
    .chapter, .sidebar {
        background: rgba(0, 0, 0, 0.7) !important;
        padding: 15px !important;
        margin: 20px !important;
        border-radius: 10px !important;
        box-shadow: 0px 0px 15px #ff6600 !important;
        color: #ffffff !important;
    }

    /* Highlight guiding questions */
    .guiding-questions, .chapter .guiding-questions {
        font-size: 18px !important;
        line-height: 1.8 !important;
        color: #ffcc00 !important;
        border-left: 4px solid #ff6600 !important;
        padding-left: 10px !important;
    }

    /* Override buttons */
    button, input[type="button"], input[type="submit"] {
        background: #ff6600 !important;
        color: white !important;
        font-size: 16px !important;
        border: none !important;
        border-radius: 5px !important;
        padding: 10px 20px !important;
        cursor: pointer !important;
        transition: all 0.3s ease-in-out !important;
    }

    button:hover, input[type="button"]:hover, input[type="submit"]:hover {
        background: #ffcc00 !important;
        color: black !important;
        transform: scale(1.1) !important;
    }

    /* Responsive design tweaks */
    @media (max-width: 768px) {
        body {
            font-size: 14px !important;
        }

        nav a {
            font-size: 14px !important;
            margin: 0 10px !important;
        }

        .chapter, .sidebar {
            padding: 10px !important;
            margin: 10px !important;
        }

        button {
            font-size: 14px !important;
            padding: 8px 16px !important;
        }
    }
}
